    let gr = g.createRadialGradient(0, 0, R * 0.8, 0, 0, R);
    gr.addColorStop(0, '#5a2d0c'); gr.addColorStop(0.6, '#8a4a1c'); gr.addColorStop(1, '#3a1a06');
