    ctx.beginPath(); ctx.ellipse(0, hy - hr * 0.35, hr * 1.25, hr * 0.28, 0, 0, Math.PI); ctx.fill();
    ctx.fillStyle = '#e8e8e8'; ctx.fillRect(-hr * 1.02, hy - hr * 0.5, hr * 2.04, hr * 0.16);
