        ctx.globalAlpha = a * 0.35; ctx.lineWidth = 2;
        ctx.beginPath(); top.forEach(([x, y], j) => (j ? ctx.lineTo(x, y + 18) : ctx.moveTo(x, y + 18))); ctx.stroke();
        // zawinięcie grzywacza + bryzgi
