        const walking = t > T0 && t < T;
        const dir = !walking ? 'S' : Math.abs(u.to.x - u.from.x) > Math.abs(u.to.y - u.from.y) ? (u.to.x > u.from.x ? 'E' : 'W') : (u.to.y > u.from.y ? 'S' : 'N');
        const step = walking ? Math.floor(t * 8) % 4 : 0;
