        const flip = side < 0; // w oryginale tył (paszcza) jest po lewej – odwracamy tak, by był od strony przedmiotu
        const mx = wx + (flip ? 1 : -1) * size * 0.2, my = wy - size * 0.36;
        // przedmiot podlatuje i zostaje pożarty
