          for (let i = 0; i < 30; i++) s.coins.push({ x: mx + rand(-20, 20), y: top + MH - 8, vx: rand(-220, 220), vy: rand(-480, -180), ph: rand(0, TAU), sp: rand(6, 14), l: 0 });
