        g.font = `bold ${Math.round(19 * isc)}px Georgia, serif`;
        g.fillStyle = 'rgba(255,255,255,0.8)'; g.fillText('ZDRAP!', SW / 2 + 1, SH / 2 - 7 * isc + 1);
        g.fillStyle = 'rgba(58,66,84,0.85)'; g.fillText('ZDRAP!', SW / 2, SH / 2 - 7 * isc);
