          const cr = [[cx - CW / 2 + 8 * isc, top + 8 * isc], [cx + CW / 2 - 8 * isc, top + 8 * isc], [cx - CW / 2 + 8 * isc, top + CH - 8 * isc], [cx + CW / 2 - 8 * isc, top + CH - 8 * isc]];
