      const dur = isOut ? Math.max(P.dur, sp.eff.minDur || 0) : P.dur; // tyle, ile ustawiono (sceny fabularne mają swoje minimum)
      const self = Object.assign(Object.create(sp.eff), { dur }); // efekty czytają this.dur
